/bin/bash -lc "cd [workspace path] && python3 -c \"
from PIL import Image
import numpy as np
a = np.array(Image.open('first_frame.png')).astype(int)
# 4-level color classification map full frame, stride 2
for y in range(0,144,3):
    line=''
    for x in range(0,256,2):
        r,g,b=a[y,x]
        if r>60 and g>60 and b>60 and abs(r-g)<18 and abs(g-b)<22:
            v=(r+g+b)//3
            line+= '#' if v>125 else ('+' if v>100 else ('.' if v>70 else ' '))
        elif r>g and r>b:
            line+='O' if r>90 else 'd'
        elif b>r and b>g:
            line+='B'
        else:
            line+='?'
    print('%3d '%y+line)
\""
